// Validate patient data
const patientData = items[0].json;

const required = ['firstName', 'lastName', 'dateOfBirth', 'email', 'phone'];
const missing = required.filter(field => !patientData[field]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Generate patient ID
patientData.patientId = `PT${Date.now()}`;
patientData.registrationDate = new Date().toISOString();
patientData.status = 'pending_verification';

return items.map(item => ({
  json: patientData
}));

// Create patient portal account
const patientData = items[0].json;

return items.map(item => ({
  json: {
    patientId: patientData.patientId,
    email: patientData.email,
    username: patientData.email,
    temporaryPassword: Math.random().toString(36).slice(-12),
    mustChangePassword: true,
    createdAt: new Date().toISOString()
  }
}));
